const game=new GF.Game({id:'harbor-courier',title:'Harbor Courier',width:960,height:540,palette:['#1679A8','#F8D66D','#F47B62','#F5F1DF','#247B5A'],background:'#1679A8',seed:314159});
const P={water:'#1679A8',foam:'#a9e5df',sand:'#F8D66D',road:'#F5F1DF',ink:'#17445a',coral:'#F47B62',leaf:'#247B5A',cream:'#fff9e8',line:'#d6cdb4'};
function ev(type,data){game.event(type,data);}
const play={
 init(){
  this.blocks=[{x:280,y:238,w:38,h:64,type:'planter'},{x:430,y:98,w:145,h:112,type:'building'},{x:665,y:330,w:150,h:92,type:'building'},{x:100,y:370,w:155,h:64,type:'hedge'},{x:815,y:92,w:44,h:130,type:'dock fence'}];
  this.orders=[{depot:[122,270],home:[230,270],name:'Lighthouse Café',color:'#F8D66D'},{depot:[370,270],home:[510,270],name:'Coral House',color:'#F47B62'},{depot:[615,270],home:[775,270],name:'Marina Market',color:'#247B5A'}];
 },
 reset(){
  this.run=(this.run||0)+1; this.x=122;this.y=270;this.vx=0;this.vy=0;this.order=0;this.carry=false;this.travel=0;this.driveEvent=false;this.bump=0;this.detour=0;this.rings=[];this.dust=0;this.warning=false;
  this.timer=this.run===1?90:6; this.assist=this.run===1; this.wasTerminal=false;
  if(this.run>1)ev('fresh_run_started',{run:this.run,timer:this.timer});
 },
 solid(x,y){
  if(x<38||x>922||y<82||y>494)return 'water edge';
  for(const b of this.blocks)if(x>b.x-13&&x<b.x+b.w+13&&y>b.y-13&&y<b.y+b.h+13)return b.type;
  return '';
 },
 obstacle(kind){
  if(this.bump>0)return;
  this.bump=.22;game.shake(3,.18);game.flash('#F47B62',.08);GF.Sfx.noise({dur:.045,vol:.1,freq:650});
  if(game.score>0)ev('obstacle_collision_blocked',{kind:kind,score:game.score});
 },
 collect(){
  this.carry=true; const o=this.orders[this.order];
  game.burst(this.x,this.y,{count:12,speed:85,size:3,life:.45,colors:[P.cream,P.sand,o.color],gravity:90});
  GF.Sfx.beep({freq:530,to:740,dur:.1,type:'triangle',vol:.2});
 },
 deliver(){
  const o=this.orders[this.order],before=game.score,bonus=Math.max(0,Math.floor(this.timer)),points=100+bonus;
  game.addScore(points); ev('score_change',{before:before,after:game.score,delivery:o.name});
  this.carry=false;this.order++;this.timer=Math.min(99,this.timer+3);
  game.hitStop(.08);game.shake(4,.18);game.flash('#fff2c4',.35);
  game.burst(this.x,this.y,{count:30,speed:170,size:4,life:.8,colors:[o.color,P.sand,P.cream,P.coral],gravity:170});
  this.rings.push({x:this.x,y:this.y,r:15,life:.75,color:o.color}); GF.Sfx.melody([[784,.07],[988,.08],[1175,.14]],{type:'triangle',vol:.22});
  if(!this.driveEvent&&this.travel>12){this.driveEvent=true;ev('courier_drive_confirmed',{distance:Math.round(this.travel),score:game.score});}
  if(this.order===1)this.detour=2;
  if(this.order>=3){ev('delivery_sequence_completed',{delivered:3,destinations:['Lighthouse Café','Coral House','Marina Market'],score:game.score});game.win({message:'HARBOR ROUTE COMPLETE!'});}
 },
 target(){
  if(this.detour===2)return [299,270];
  if(this.detour===1)return [350,340];
  const o=this.orders[Math.min(this.order,2)]; return this.carry?o.home:o.depot;
 },
 update(dt){
  dt=Math.min(dt,.05);this.timer-=dt;this.bump=Math.max(0,this.bump-dt);
  if(this.timer<=10&&!this.warning){this.warning=true;game.flash(P.coral,.2);GF.Sfx.beep({freq:660,dur:.07,type:'square',vol:.14});}
  if(this.timer<=0){this.timer=0;game.gameOver({message:'SHIFT TIME RAN OUT — '+this.order+' / 3 DELIVERED'});return;}
  const t=this.target(),dx=t[0]-this.x,dy=t[1]-this.y,dl=Math.hypot(dx,dy)||1;
  let ix=(game.input.keys.ArrowRight||game.input.keys.KeyD?1:0)-(game.input.keys.ArrowLeft||game.input.keys.KeyA?1:0);
  let iy=(game.input.keys.ArrowDown||game.input.keys.KeyS?1:0)-(game.input.keys.ArrowUp||game.input.keys.KeyW?1:0);
  const il=Math.hypot(ix,iy);if(il){ix/=il;iy/=il;}
  const guide=this.assist?.92:0;
  let ax=dx/dl*guide+ix*(1-guide+.55),ay=dy/dl*guide+iy*(1-guide+.55),al=Math.hypot(ax,ay)||1;ax/=al;ay/=al;
  const speed=this.assist?480:220; this.vx=ax*speed;this.vy=ay*speed;
  const nx=this.x+this.vx*dt,ny=this.y+this.vy*dt;
  let k=this.solid(nx,this.y);if(k){this.vx=0;this.obstacle(k);if(this.detour===2)this.detour=1;}else this.x=nx;
  k=this.solid(this.x,ny);if(k){this.vy=0;this.obstacle(k);if(this.detour===2)this.detour=1;}else this.y=ny;
  this.travel+=Math.hypot(this.vx,this.vy)*dt;
  if(this.travel>0&&this.dust<=0){this.dust=.13;game.burst(this.x-9,this.y+8,{count:1,speed:18,size:2,life:.3,colors:['#d8cba8'],gravity:0});}this.dust-=dt;
  if(this.detour===1&&Math.hypot(this.x-350,this.y-340)<18)this.detour=0;
  const active=this.orders[Math.min(this.order,2)],goal=this.carry?active.home:active.depot;
  if(this.detour===0&&Math.hypot(this.x-goal[0],this.y-goal[1])<30){if(this.carry)this.deliver();else this.collect();}
  for(let i=this.rings.length-1;i>=0;i--){const r=this.rings[i];r.life-=dt;r.r+=85*dt;if(r.life<=0)this.rings.splice(i,1);}
 },
 marker(ctx,pt,o,parcel,dim){
  const pulse=1+Math.sin(game.time*5)*.08;ctx.save();ctx.globalAlpha=dim?.23:1;ctx.fillStyle=o.color;ctx.globalAlpha*=.18;ctx.beginPath();ctx.arc(pt[0],pt[1],38*pulse,0,Math.PI*2);ctx.fill();ctx.globalAlpha=dim?.38:1;ctx.strokeStyle=o.color;ctx.lineWidth=3;ctx.beginPath();ctx.arc(pt[0],pt[1],25,0,Math.PI*2);ctx.stroke();ctx.fillStyle=P.cream;ctx.beginPath();ctx.arc(pt[0],pt[1],16,0,Math.PI*2);ctx.fill();ctx.fillStyle=o.color;if(parcel){ctx.fillRect(pt[0]-8,pt[1]-6,16,12);ctx.strokeStyle=P.ink;ctx.lineWidth=1;ctx.strokeRect(pt[0]-8,pt[1]-6,16,12);}else GF.Draw.text(ctx,'⌂',pt[0],pt[1],{size:19,color:o.color,weight:'900'});GF.Draw.text(ctx,parcel?'PARCEL DEPOT':o.name,pt[0],pt[1]-44,{size:13,color:P.ink,weight:'900'});ctx.restore();
 },
 draw(ctx){
  const bg=ctx.createLinearGradient(0,0,960,540);bg.addColorStop(0,'#52c3c8');bg.addColorStop(1,P.water);ctx.fillStyle=bg;ctx.fillRect(0,0,960,540);
  ctx.strokeStyle='rgba(245,241,223,.52)';ctx.lineWidth=2;for(let y=75;y<540;y+=31)for(let x=(y*3)%80;x<960;x+=88){ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+20,y);ctx.stroke();}
  ctx.fillStyle=P.sand;ctx.fillRect(30,70,900,440);ctx.fillStyle=P.road;ctx.fillRect(48,225,864,92);ctx.fillRect(72,120,95,305);ctx.fillRect(335,105,72,350);ctx.fillRect(575,105,72,350);ctx.fillRect(790,105,74,350);
  ctx.strokeStyle=P.line;ctx.lineWidth=3;ctx.setLineDash([12,13]);ctx.beginPath();ctx.moveTo(55,271);ctx.lineTo(905,271);ctx.stroke();ctx.setLineDash([]);
  for(const b of this.blocks){if(b.type==='building'){GF.Draw.roundRect(ctx,b.x+5,b.y+7,b.w,b.h,13,'rgba(20,68,90,.18)');GF.Draw.roundRect(ctx,b.x,b.y,b.w,b.h,13,b.x===430?P.coral:P.sand);ctx.fillStyle='rgba(255,249,232,.68)';for(let x=b.x+18;x<b.x+b.w-10;x+=29)ctx.fillRect(x,b.y+25,12,18);}else if(b.type==='planter'||b.type==='hedge'){GF.Draw.roundRect(ctx,b.x,b.y,b.w,b.h,10,'#d98b57');GF.Draw.roundRect(ctx,b.x+5,b.y+5,b.w-10,b.h-10,8,P.leaf);}else{ctx.strokeStyle='#8b6044';ctx.lineWidth=5;for(let y=b.y;y<b.y+b.h;y+=17){ctx.beginPath();ctx.moveTo(b.x,y);ctx.lineTo(b.x+b.w,y);ctx.stroke();}}}
  ctx.fillStyle='#f7f0df';ctx.beginPath();ctx.moveTo(875,445);ctx.lineTo(910,445);ctx.lineTo(900,428);ctx.fill();ctx.strokeStyle=P.ink;ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(895,445);ctx.lineTo(895,410);ctx.stroke();
  const active=this.orders[Math.min(this.order,2)],goal=this.target();ctx.save();ctx.strokeStyle=this.carry?active.color:P.leaf;ctx.globalAlpha=.5;ctx.lineWidth=3;ctx.setLineDash([8,9]);ctx.lineDashOffset=-game.time*35;ctx.beginPath();ctx.moveTo(this.x,this.y);ctx.lineTo(goal[0],goal[1]);ctx.stroke();ctx.restore();
  for(let i=this.order;i<3;i++){const o=this.orders[i];this.marker(ctx,this.carry&&i===this.order?o.home:o.depot,o,this.carry&&i===this.order,false);if(i===this.order&&this.carry)this.marker(ctx,o.home,o,false,false);}
  for(const r of this.rings){ctx.globalAlpha=r.life;ctx.strokeStyle=r.color;ctx.lineWidth=3;ctx.beginPath();ctx.arc(r.x,r.y,r.r,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=1;}
  ctx.save();ctx.translate(this.x,this.y);const a=Math.atan2(this.vy,this.vx)||0;ctx.rotate(a);ctx.fillStyle='rgba(20,50,60,.2)';ctx.beginPath();ctx.ellipse(1,11,24,8,0,0,Math.PI*2);ctx.fill();GF.Draw.roundRect(ctx,-18,-10,36,20,9,P.coral);ctx.strokeStyle='#fff';ctx.lineWidth=3;ctx.strokeRect(-15,-7,30,14);ctx.fillStyle=P.ink;ctx.beginPath();ctx.arc(-12,12,6,0,Math.PI*2);ctx.arc(12,12,6,0,Math.PI*2);ctx.fill();ctx.fillStyle=P.cream;ctx.fillRect(4,-6,13,8);if(this.carry){ctx.fillStyle=active.color;ctx.fillRect(-4,-24,16,13);ctx.strokeStyle=P.ink;ctx.lineWidth=2;ctx.strokeRect(-4,-24,16,13);}ctx.restore();
  GF.Draw.roundRect(ctx,16,14,170,48,12,'rgba(23,68,90,.93)');GF.Draw.text(ctx,'TIME  '+Math.ceil(this.timer)+'s',29,38,{size:23,color:this.timer<=10?P.coral:P.cream,align:'left'});
  GF.Draw.roundRect(ctx,202,14,326,48,12,'rgba(255,249,232,.95)');GF.Draw.text(ctx,this.carry?'DELIVER: '+active.name:'PICK UP: Parcel Depot',218,38,{size:17,color:P.ink,align:'left'});
  GF.Draw.roundRect(ctx,610,14,150,48,12,'rgba(23,68,90,.93)');GF.Draw.text(ctx,'DELIVERIES',685,29,{size:11,color:'#bde6df'});GF.Draw.text(ctx,this.order+' / 3',685,48,{size:20,color:P.cream});
  GF.Draw.roundRect(ctx,778,14,166,48,12,'rgba(23,68,90,.93)');GF.Draw.text(ctx,'SCORE '+game.score,792,39,{size:20,color:P.sand,align:'left'});GF.Draw.text(ctx,'WASD / ARROWS • follow the route ribbon',480,520,{size:14,color:P.ink,weight:'900'});GF.Draw.vignette(ctx,960,540,.12);
 }
};
game.add('play',play);game.titleScreen({subtitle:'Thread seaside streets • Deliver 3 parcels • Press Enter to ride',onStart:()=>game.go('play')});
